"""Generate the static site and identical legal pages; no deployment side effects."""
from pathlib import Path
from html import escape
import base64, hashlib, json

ROOT = Path(__file__).resolve().parent.parent
DATE = '2026-09-28'
STORE = 'https://apps.apple.com/app/feedfare/id6758923557'
# Set only from a campaign link generated by App Store Connect. No invented tokens.
PROVIDER_TOKEN = '1329661'

def store_link(placement):
    return STORE + (f'?pt={PROVIDER_TOKEN}&amp;ct=site_{placement}&amp;mt=8' if PROVIDER_TOKEN else '')

def cta(placement, label='View on the App Store', extra=''):
    return f'<a class="button {extra}" href="{store_link(placement)}">{label}<span aria-hidden="true">↗</span></a>'

def header():
    return '''<a class="skip-link" href="#main">Skip to content</a>
<header class="site-header"><nav class="wrap nav" aria-label="Main navigation">
<a class="brand" href="https://feedfare.app/" aria-label="FeedFare home"><img src="assets/app-icon-64.webp?v=build29" srcset="assets/app-icon-128.webp?v=build29 2x" width="38" height="38" alt="" decoding="async"><span translate="no">FeedFare</span></a>
<div class="nav-links"><a href="https://feedfare.app/#how-it-works">How it works</a><a href="https://feedfare.app/#the-app">The app</a><a href="https://feedfare.app/#faq">FAQ</a><a href="https://feedfare.app/support.html">Support</a></div>
''' + cta('navigation','Get FeedFare','button-small') + '</nav></header>'

def footer():
    return '''<footer class="footer"><div class="wrap"><div class="footer-top"><a class="brand" href="https://feedfare.app/"><img src="assets/app-icon-64.webp?v=build29" width="32" height="32" alt="" loading="lazy"><span translate="no">FeedFare</span></a><nav class="footer-links" aria-label="Footer navigation"><a href="https://feedfare.app/#about">About</a><a href="https://feedfare.app/support.html">Support</a><a href="https://feedfare.app/privacy-policy.html">Privacy</a><a href="https://feedfare.app/terms.html">Terms</a><a href="https://nickrae.net">Made by Nick Rae ↗</a></nav></div><div class="footer-bottom"><span>© 2026 Nick Rae. A little movement. A better balance.</span><span>Made for your day, not your attention.</span></div></div></footer>'''

def page(title,description,path,body,schema=None,script=False,noindex=False):
    structured = json.dumps(schema,separators=(',',':'),ensure_ascii=False) if schema else ''
    digest = base64.b64encode(hashlib.sha256(structured.encode()).digest()).decode() if structured else ''
    script_policy = "'self'" + (f" 'sha256-{digest}'" if structured else '')
    policy = f"default-src 'none'; base-uri 'none'; object-src 'none'; script-src {script_policy}; style-src 'self'; img-src 'self'; font-src 'self'; connect-src 'none'; form-action 'none'; upgrade-insecure-requests"
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<meta http-equiv="Content-Security-Policy" content="{policy}">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="referrer" content="strict-origin-when-cross-origin">
<meta name="theme-color" content="#f5f6f9">
<title>{escape(title)}</title><meta name="description" content="{escape(description,quote=True)}">
<link rel="canonical" href="https://feedfare.app/{path}">
<link rel="icon" href="assets/favicon.png?v=build29" type="image/png"><link rel="apple-touch-icon" href="assets/apple-touch-icon.png?v=build29">
<meta name="apple-itunes-app" content="app-id=6758923557">
<meta property="og:type" content="website"><meta property="og:url" content="https://feedfare.app/{path}"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:image" content="https://feedfare.app/og-image.png?v=build29"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="FeedFare — Walk first. Scroll later. A preview of the new native app.">
<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{escape(title,quote=True)}"><meta name="twitter:description" content="{escape(description,quote=True)}"><meta name="twitter:image" content="https://feedfare.app/og-image.png?v=build29">
{'<meta name="robots" content="noindex">' if noindex else ''}
<link rel="stylesheet" href="assets/site.css?v=20260928">
{'<script type="application/ld+json">'+structured+'</script>' if structured else ''}
{'<script src="assets/site.js?v=20260928" defer></script>' if script else ''}
</head><body id="top">{header()}{body}{footer()}</body></html>'''

def image(name,alt,hero=False):
    loading = 'fetchpriority="high"' if hero else 'loading="lazy"'
    return f'<img src="assets/{name}-native-480.webp" srcset="assets/{name}-native-480.webp 480w, assets/{name}-native-800.webp 800w" sizes="{("(max-width: 800px) 215px, 250px" if hero else "(max-width: 600px) 125px, 180px")}" width="480" height="1044" alt="{escape(alt,quote=True)}" {loading} decoding="async">'

faq = [
('How do steps become screen time?', 'Choose your walking rule in FeedFare. The native preview defaults to 100 steps earning 5 minutes. For example, 500 steps earns 25 minutes at that setting. Earned minutes are used for timed sessions; the rule and any limits depend on your installed version.'),
('Which permissions does FeedFare need?', 'Apple Health access lets FeedFare read step counts. Motion &amp; Fitness provides live step counting. Screen Time access lets you choose apps to protect. Reminders are optional. <a href="support.html#permissions">See the setup guide</a> for what each permission does.'),
('Is the new design available now?', 'The screenshots show the new native version currently being tested in TestFlight, with example data. The App Store version may look different. Check the App Store for the current release, pricing, and compatibility.'),
('Is FeedFare a one-time purchase?', 'The current App Store release is free to download with optional in-app purchases. We are preparing a paid-download release with the full app included. That change is not live yet. Existing subscriptions must still be managed separately with Apple; updating or deleting the app does not cancel them.'),
('Does it work with Apple Watch steps?', 'FeedFare can read steps that a compatible Apple Watch has synced to Apple Health on your iPhone. Those updates can arrive later. Open FeedFare and refresh if the total has not caught up. You do not need a watch to count steps with your iPhone.'),
('What happens when a session ends?', 'In the native preview, a session gives access to one selected app for the time you choose. Other selected apps stay protected, and the selected app is protected again when the session ends. Protection depends on Screen Time authorization. <a href="support.html#screen-time">Get help with app protection</a>.'),
('Which devices are supported?', 'The current App Store listing supports iPhone and iPad with iOS or iPadOS 15.1 or later. The native preview requires iOS or iPadOS 17 or later; its appearance adapts to the system, including Liquid Glass on supported versions. The App Store lists the requirements for the version you can download.')
]
faq_html=''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in faq)
body='''<main id="main"><section class="hero wrap" aria-labelledby="hero-title"><div class="hero-copy"><p class="eyebrow"><span class="eyebrow-dot" aria-hidden="true"></span>A little movement. A better balance.</p><h1 id="hero-title">Walk first.<span>Scroll later.</span></h1><p class="hero-description">Turn your steps into time for the apps you choose. Make room for a walk before your next scroll.</p><div class="hero-actions">'''+cta('hero')+'''<a class="text-link" href="#how-it-works">Find your rhythm <span aria-hidden="true">↓</span></a></div><p class="store-note">For iPhone and iPad. Current pricing and availability on the App Store.</p></div><figure class="hero-visual"><div class="product-stage"><span class="preview-badge">Native preview · In TestFlight</span><div class="stage-orbit" aria-hidden="true"></div><div class="phone">'''+image('dashboard','Native preview dashboard with example steps, earned minutes, and the walking rule.',True)+'''</div><div class="earn-chip" aria-hidden="true"><span>Your walking rule</span><strong>100 steps → 5 min</strong></div></div><figcaption class="native-caption"><strong>A look at the new native FeedFare.</strong><br>In TestFlight · example data · App Store version may differ.</figcaption></figure></section>
<section class="section border-top wrap" id="how-it-works" aria-labelledby="how-title"><div class="section-head"><div><p class="eyebrow">Small steps, on your terms</p><h2 id="how-title">A better reason<br>to put your phone down.</h2></div><p>Your next scroll can start with a little movement. FeedFare helps you make that connection.</p></div><div class="how-grid"><article class="step"><span class="step-number" aria-hidden="true">01</span><h3>Choose your apps.</h3><p>Pick the apps you reach for out of habit. Screen Time access lets FeedFare help you protect that space.</p></article><article class="step"><span class="step-number" aria-hidden="true">02</span><h3>Take a walk.</h3><p>Set a walking rule that fits your day. Your iPhone’s steps become earned screen time.</p></article><article class="step"><span class="step-number" aria-hidden="true">03</span><h3>Make time yours.</h3><p>Use what you earn for a session, then return to your day. A little more intention, one walk at a time.</p></article></div><div class="rule-panel"><div><h3>What could your walk earn?</h3><p>An example using the native preview’s default rule: every 100 steps earns 5 minutes. You can change your rule in the app.</p></div><div><div class="rule-form"><div class="rule-input"><label for="example-steps">Steps in your walk</label><select id="example-steps" name="example-steps"><option value="100">100 steps</option><option value="500" selected>500 steps</option><option value="1000">1,000 steps</option><option value="2000">2,000 steps</option></select></div><span class="rule-arrow" aria-hidden="true">→</span><div class="rule-result"><span>Time you could earn</span><output id="example-minutes" for="example-steps" aria-live="polite" aria-atomic="true">25 min</output></div></div><noscript><p class="noscript-note">Example: 500 steps earns 25 minutes. Enable JavaScript to try other amounts.</p></noscript></div></div><p class="footnote">An illustration, not a step tracker. Features and limits depend on your installed version.</p></section>
<section class="section preview-section" id="the-app" aria-labelledby="preview-title"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Native preview · currently in TestFlight</p><h2 id="preview-title">Less noise.<br>More of your day.</h2></div><p>Familiar iOS controls, a clear view of your progress, and a little encouragement to keep moving.</p></div><div class="preview-layout"><article class="preview-card"><div class="preview-card-copy"><h3>See the little<br>wins add up.</h3><p>A simple daily history of your steps and earned minutes.</p><a class="text-link" href="assets/activity-native-800.webp">View full Activity screen <span aria-hidden="true">↗</span></a></div><div class="screenshot-window">'''+image('activity','Native preview Activity screen showing example daily steps and earned minutes.')+'''</div></article><article class="preview-card"><div class="preview-card-copy"><h3>Find your<br>own momentum.</h3><p>Your recent movement, earned time, and streaks in one place.</p><a class="text-link" href="assets/stats-native-800.webp">View full Stats screen <span aria-hidden="true">↗</span></a></div><div class="screenshot-window">'''+image('stats','Native preview Stats screen with an example weekly steps chart.')+'''</div></article></div><p class="preview-note">Actual simulator screens from the native preview, using example data. The preview requires iOS 17 or later and adapts to the system appearance. The released App Store app may look and behave differently while testing continues.</p></div></section>
<section class="section wrap privacy-row" aria-labelledby="privacy-title"><div><p class="eyebrow">Thoughtfully connected</p><h2 id="privacy-title">Your steps.<br>Your choices.</h2><a class="text-link" href="privacy-policy.html">Read our privacy policy <span aria-hidden="true">↗</span></a></div><ul class="privacy-points"><li><strong>Connect only what the feature needs.</strong><p>Health reads step counts. Motion supplies live steps. Screen Time enables app protection. Optional reminders are your choice.</p></li><li><strong>Local progress in the native app.</strong><p>The native preview stores your walking history and app selections on your device. It has no advertising or analytics SDK. Device backups follow your Apple settings.</p></li><li><strong>Clear help when something needs attention.</strong><p>Permission settings and delayed step updates can affect the experience. Our <a href="support.html">setup and troubleshooting guide</a> walks you through them.</p></li></ul></section>
<section class="wrap" id="download" aria-labelledby="download-title"><div class="availability"><div><p class="eyebrow">Make room for a little movement</p><h2 id="download-title">Your time,<br>well earned.</h2><p>Start with the FeedFare version available on the App Store today.</p>'''+cta('download',extra='button-light')+'''</div><div class="availability-notes"><h3>A simpler purchase model is on the way.</h3><p>The current release is free to download with optional in-app purchases. The native paid-download release is being tested, with the full app included.</p><p>Until it launches, the App Store shows the current offer. Already subscribed? <a href="support.html#billing">Manage your existing subscription</a>.</p></div></div></section>
<section class="section wrap faq-layout" id="faq" aria-labelledby="faq-title"><div class="faq-intro"><p class="eyebrow">A few helpful answers</p><h2 id="faq-title">Before your<br>first walk.</h2><p>From connecting your steps to managing previous purchases.</p><a class="text-link" href="support.html">Visit support <span aria-hidden="true">↗</span></a></div><div class="faq-list">'''+faq_html+'''</div></section>
<section class="about wrap" id="about" aria-labelledby="about-title"><h2 id="about-title">Made for a more<br>intentional everyday.</h2><p>FeedFare is an independent app by Nick Rae. The idea is simple: give a little movement a place in the moments you would otherwise spend scrolling. Choose your rule, find your pace, and build a routine that works for you.</p></section></main>'''
schema={'@context':'https://schema.org','@type':'SoftwareApplication','name':'FeedFare','applicationCategory':'HealthApplication','operatingSystem':'iOS 15.1 or later; iPadOS 15.1 or later','url':'https://feedfare.app/','downloadUrl':STORE,'description':'Turn your daily steps into earned screen time for the apps you choose.','author':{'@type':'Person','name':'Nick Rae','url':'https://nickrae.net'}}
(ROOT/'index.html').write_text(page('FeedFare — Walk first. Scroll later.','Turn your steps into earned screen time. Choose your apps, find your walking rule, and make room for a little movement. FeedFare for iPhone and iPad.','',body,schema,True))

privacy='''<p class="legal-date">Updated and effective September 28, 2026</p><div class="callout"><p><strong>FeedFare turns steps into screen time.</strong> This policy covers the FeedFare app, its native TestFlight preview, and this website.</p></div>
<h2>1. Who is responsible</h2><p>FeedFare is developed by Nick Rae in Merced, California. For questions or privacy requests, email <a href="mailto:nick@nickrae.net">nick@nickrae.net</a>. You do not need to create a FeedFare account to use the app.</p>
<h2>2. Steps, progress, and app protection</h2><p>With your permission, FeedFare reads step counts from Apple Health and uses your device’s Motion &amp; Fitness data for step counting. This supports walking goals, earned screen time, history, and streaks. Apple Watch steps may be included after they sync to Apple Health. FeedFare does not write or change your Health records.</p><p>Your goals, preferences, progress, earned balance, and sessions are stored in the app’s local storage. In the native version, Screen Time provides opaque selection tokens for the apps you choose. The app and its protection extensions share selection and session state in an on-device App Group. The native app does not send those tokens or step history to a FeedFare server.</p><p>The native version may import existing FeedFare progress and keep a local migration backup. Device or iCloud backups are governed by your Apple backup settings; on-device storage does not mean that the operating system can never back it up.</p>
<h2>3. Permissions and optional features</h2><ul><li><strong>Health:</strong> reading steps for progress and earned time.</li><li><strong>Motion &amp; Fitness:</strong> live step counting on the device.</li><li><strong>Screen Time:</strong> selecting and protecting apps and managing timed access.</li><li><strong>Notifications:</strong> optional reminders that you can turn off.</li><li><strong>Sharing:</strong> when you choose to share a milestone, the information in that image goes to the app or recipient you select.</li></ul><p>FeedFare does not need contacts or location to provide its walking features. You can revoke permissions in iOS settings. Features that need a revoked permission may stop working. See <a href="https://feedfare.app/support.html#permissions">permission help</a>.</p>
<h2>4. Purchases: released app and native preview</h2><p>Apple processes App Store purchases and subscriptions. FeedFare does not receive your payment-card details. Older subscription versions use RevenueCat to validate purchases and determine access. This can involve purchase history, transaction or receipt information, subscription status, and a pseudonymous app user identifier. RevenueCat does not receive your step counts through FeedFare’s purchase integration.</p><p>The native TestFlight version does not include the RevenueCat SDK, advertising SDKs, or a third-party analytics SDK. Apple still handles app acquisition and any previous subscription records. Updating or deleting FeedFare does not cancel a subscription.</p><p>See <a href="https://www.revenuecat.com/privacy">RevenueCat’s privacy policy</a> and <a href="https://www.apple.com/legal/privacy/">Apple’s privacy policy</a> for their services.</p>
<h2>5. Website, diagnostics, and support</h2><p>This website is hosted on GitHub Pages. GitHub and its delivery providers process technical request information, such as IP address, browser details, and request logs, to serve and protect the site. See <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub’s privacy statement</a>. Fonts, styles, and images used by the page are served with the site. We do not add advertising pixels, analytics cookies, or a third-party website tracking SDK.</p><p>App Store links may include a campaign label identifying where the link was placed. Apple can provide campaign-level acquisition reports subject to its reporting rules. Those labels do not include your Health data, Screen Time selections, or a personal identifier generated by this website.</p><p>Apple may provide app diagnostics or TestFlight feedback according to your Apple sharing settings and any feedback you choose to send. If you contact support, we receive your email address and the information you include. Send only what is needed to explain the issue; private Health records are not required.</p>
<h2>6. Sharing and use</h2><p>We use information to provide the features you choose, handle purchase access in subscription versions, respond to support requests, and maintain the app and website. We do not sell personal information or use step data or Screen Time selections for advertising. Service providers process the information needed for their roles described above. Information may also be disclosed when required by law or to protect legal rights and security.</p>
<h2>7. Retention, reset, and your choices</h2><p>Local app progress remains until you reset it or remove the app and its data. The native app’s <strong>Reset local data</strong> control clears saved progress, preferences, migration backups, protection, and scheduled reminders. It does not delete Apple Health records, cancel subscriptions, or remove separate device backups. Manage those with Apple. Removing local data cannot recall a milestone that you already shared.</p><p>We keep support correspondence for as long as needed to handle the request and related follow-up, or meet applicable legal obligations. Purchase providers may retain transaction records under their own retention policies and legal obligations. Contact us to request access, correction, or deletion of information we hold about you, or to ask about applicable privacy rights. We may need to verify a request. We cannot retrieve step history that exists only on your device.</p>
<h2>8. Children and security</h2><p>FeedFare is a general-audience app and does not offer child accounts or a child-directed social service. A parent or guardian should supervise use by children and use Apple’s age, purchase, and permission controls. Contact us if you believe a child has sent personal information to us so we can address it.</p><p>We use the platform’s app storage and permission mechanisms and HTTPS for this website. No storage or transmission method is completely secure. Keep your device and operating system up to date.</p>
<h2>9. Policy updates</h2><p>We will update this page when the app’s practices change and revise the date above. Material changes will be explained here and, when appropriate, in the app or its release information. Where required, we will request consent before a new use of information.</p><p><a href="mailto:nick@nickrae.net">Contact Nick Rae about privacy</a></p>'''

terms='''<p class="legal-date">Updated and effective September 28, 2026</p><div class="callout"><p>These terms cover FeedFare’s walking and screen-time features. Purchases, refunds, and subscriptions also follow the applicable Apple App Store terms. The native version shown on this website is currently a TestFlight preview.</p></div>
<h2>1. Using FeedFare</h2><p>FeedFare is an independent app developed by Nick Rae. It helps you connect walking with intentional screen time. Use it lawfully and only on devices you are authorized to manage. You do not need a FeedFare account. If you are not legally able to agree to these terms, use the app with a parent or guardian who agrees on your behalf. Apple’s age, account, and purchase requirements also apply.</p>
<h2>2. Permissions and feature availability</h2><p>Step tracking depends on Health and/or Motion access. App protection depends on Screen Time authorization and Apple’s system services. Reminders are optional. Features, limits, and appearance may differ between the released app and TestFlight builds. Permission changes, system restrictions, device settings, and delayed Health updates can affect operation.</p><p>FeedFare is not an unbreakable lock, a security system, medical advice, or a promise of a particular health or behavior outcome. Choose activity appropriate for your circumstances and keep access to anything essential. Do not use the app as the sole way to supervise another person or enforce a safety-critical restriction.</p>
<h2>3. Purchases and previous subscriptions</h2><p>The App Store shows the current price, purchase terms, eligibility, and supported devices for the version available in your region. As of this update, the public release is free to download with optional in-app purchases. A native paid-download release with the full app included is in testing and is not yet the public offer. This page does not change an existing purchase or subscription.</p><p>If you subscribed to an earlier version, the subscription follows the offer you accepted through Apple and may renew until canceled. An app update, local reset, or deletion does not cancel it. Review or cancel it in <a href="https://apps.apple.com/account/subscriptions">Apple’s subscription settings</a>. Any transition away from subscriptions will be explained separately; do not assume a TestFlight installation ends billing.</p><p>Apple processes payment and determines eligibility for App Store refunds under its policies and applicable law. <a href="https://support.apple.com/en-us/118223">Learn how to request a refund from Apple</a>. Nothing here takes away mandatory consumer rights.</p>
<h2>4. Your information</h2><p>Our <a href="https://feedfare.app/privacy-policy.html">privacy policy</a> explains step data, local storage, permissions, legacy purchase processing, support messages, and website hosting. You choose whether to share a milestone through your device’s share sheet. Share only information you are comfortable sending to the selected destination.</p>
<h2>5. Ownership and license</h2><p>FeedFare’s software, branding, and original content belong to Nick Rae or their respective licensors. Your use of the app is subject to Apple’s applicable software license and these terms. Do not copy or redistribute the app or misuse its services except as permitted by the license or applicable law. These terms do not give us a license to publish your private step history.</p>
<h2>6. Availability and limitations</h2><p>We aim to keep FeedFare useful and reliable, but do not guarantee uninterrupted availability, perfect step counts, or protection in every device state. The app is provided as available, subject to warranties and rights that cannot lawfully be excluded. TestFlight software may change or expire. We may update features and will communicate material changes to paid access when required.</p><p>To the extent permitted by applicable law, Nick Rae is not liable for indirect or consequential losses resulting from use of FeedFare, and total liability is limited to the greater of the amount you paid for FeedFare in the preceding 12 months or US $50. These limits do not apply where prohibited by law and do not limit rights that cannot be waived.</p>
<h2>7. Changes and contact</h2><p>We may update these terms to reflect changes to FeedFare or applicable requirements. The updated date will appear here, with notice of material changes where required. California law governs these terms to the extent it does not override mandatory protections where you live. Contact <a href="mailto:nick@nickrae.net">nick@nickrae.net</a> with questions about FeedFare or these terms.</p>'''

support='''<p>Start with the guide for your installed version. The new native design is in TestFlight; the current App Store release may use different button names.</p><nav class="toc" aria-label="Support topics"><a href="#permissions">Permissions</a><a href="#steps">Step updates</a><a href="#screen-time">App protection</a><a href="#billing">Purchases</a><a href="#reset">Reset</a><a href="#contact">Contact</a></nav>
<h2 id="permissions">Connect the features you want</h2><ul><li><strong>Apple Health:</strong> in FeedFare Settings, choose Connect or refresh Health and allow access to step counts. You can review access from Apple Health’s app permissions.</li><li><strong>Motion &amp; Fitness:</strong> use Enable live steps. If permission was denied, review FeedFare under iPhone Settings → Privacy &amp; Security → Motion &amp; Fitness, then return and retry.</li><li><strong>Screen Time:</strong> choose Connect Screen Time and complete Apple’s authorization prompt. On the native preview, an existing connection shows Manage protected apps instead.</li><li><strong>Reminders:</strong> choose whether to enable the evening check-in. You can change notification permission in iPhone Settings.</li></ul><p>System restrictions can prevent permission changes. If an option is unavailable on a managed device, check with the person who manages it. Do not share your Apple Account password with support.</p>
<h2 id="steps">My steps are not updating</h2><ol><li>Check that Apple Health itself has recent step data and that FeedFare has access to it.</li><li>Open FeedFare and use Refresh steps or Connect or refresh Health. Apple Watch data may need time to sync to your iPhone.</li><li>For live iPhone counting, enable Motion &amp; Fitness and keep your phone with you as you walk. In the native preview, Refresh live steps shows progress and a result, a waiting state, or guidance.</li><li>If a connection is already authorized, iOS may not show another permission prompt. Check the status and latest response instead.</li></ol><p>Live Motion updates are a foreground feature. Background Health updates can arrive later; earned totals may not change immediately while FeedFare is closed. Opening the app refreshes available data. The website’s walking example does not read or track your actual steps.</p>
<h2 id="screen-time">My apps are not protected</h2><ol><li>Check that FeedFare has Screen Time authorization. Open Apps or Settings and connect if needed.</li><li>In the native preview, use Manage protected apps or Choose protected apps. Pick individual apps, or choose a category to add its current apps. Newly installed apps need to be selected later.</li><li>Save the selection. The native preview supports up to 50 selected apps and does not protect websites. It explains mixed selections before saving.</li><li>End an active session before changing the protected selection. A native session unlocks one chosen app while other selected apps remain protected.</li></ol><p>If protection does not return after a session ends, open FeedFare to reconcile the session, check authorization, and contact support with the app version and what happened. Screen Time permissions and system behavior can affect enforcement.</p>
<h2>Goals, streaks, and earned minutes</h2><p>In the native preview, the default earning rule is 100 steps for 5 minutes. Change it in Settings. Changes apply to future credits; they do not rewrite the existing balance. Unused balance carries over. Streaks use a separate 1,000-step daily milestone, so changing your daily goal does not change the streak threshold. Features and limits in the public subscription version may differ.</p>
<h2 id="billing">Purchases and existing subscriptions</h2><p>The App Store is the source for current regional prices and offers. The public app currently has optional in-app purchases. The native full-app paid-download release is being tested; this website does not change your billing.</p><ul><li><a href="https://support.apple.com/en-us/118428">Manage or cancel a subscription with Apple</a>. On iPhone, open Settings, tap your name, then Subscriptions.</li><li><a href="https://support.apple.com/en-us/118223">Request a refund from Apple</a>. Eligibility depends on Apple’s policies and applicable law.</li><li>If access is missing in a subscription version, use its Restore Purchases control with the Apple Account that made the purchase.</li><li>The native preview does not require an in-app PRO purchase. If you previously subscribed, review that subscription separately. Installing an update or TestFlight build does not cancel renewal.</li></ul>
<h2 id="reset">Resetting local data</h2><p>In the native preview, Settings → Reset local data removes saved progress, balance, preferences, migration backups, app protection, and scheduled reminders on that device. This cannot be undone within the app. It does not delete Apple Health data, manage device backups, or cancel a subscription. Review what you need to keep before confirming a reset.</p>
<h2 id="contact">Still need a hand?</h2><p>Email <a href="mailto:nick@nickrae.net?subject=FeedFare%20support">nick@nickrae.net</a> with your FeedFare version/build, iOS version, what you tapped, and what you expected to happen. The native preview shows its build in Settings → About FeedFare. Please leave out private Health records, passwords, payment details, and Screen Time tokens. A screenshot with personal information removed can help.</p>'''

for path,title,desc,content in [('privacy-policy.html','Privacy Policy','How FeedFare handles step counts, Screen Time selections, purchases, local data, and website requests.',privacy),('terms.html','Terms of Use','FeedFare terms for walking features, app protection, purchases, and the native preview.',terms),('support.html','A little help, when you need it.','Help with FeedFare permissions, step updates, Screen Time, subscriptions, and local data.',support)]:
    body=f'<main id="main" class="wrap document"><div class="page-hero"><p class="eyebrow">FeedFare · {("Support" if path=="support.html" else "Clear, useful information")}</p><h1>{title}</h1></div>{content}</main>'
    (ROOT/path).write_text(page(f'{title} — FeedFare',desc,path,body))

(ROOT/'404.html').write_text(page('Page not found — FeedFare','Find your way back to FeedFare.','404.html','<main id="main" class="wrap not-found"><p class="eyebrow">404 · A small detour</p><h1>Let’s get you<br>back on your path.</h1><p>That page is not here. Your next step is.</p><a class="button" href="https://feedfare.app/">Back to FeedFare <span aria-hidden="true">↗</span></a></main>',noindex=True).replace('href="assets/','href="https://feedfare.app/assets/').replace('src="assets/','src="https://feedfare.app/assets/'))
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'  <url><loc>https://feedfare.app/{p}</loc><lastmod>{DATE}</lastmod></url>\n' for p in ['','privacy-policy.html','terms.html','support.html'])+'</urlset>\n')
(ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\n\nSitemap: https://feedfare.app/sitemap.xml\n')
(ROOT/'.nojekyll').touch()
print('Generated homepage, support, policies, 404, and sitemap.')
